import { createRequire } from "node:module";
import assert from "node:assert/strict";
const { chromium } = createRequire(import.meta.url)("playwright");
const [base, executablePath, token] = process.argv.slice(2);
const browser = await chromium.launch({ executablePath, headless: true });
const context = await browser.newContext({ viewport: { width: 390, height: 844 } });
try {
  assert.equal((await context.request.post(base + "/api/login", { data: { token } })).status(), 200);
  const page = await context.newPage();
  page.on("pageerror", (e) => console.error("pageerror:", e.message));
  const open = async (hash) => { await page.goto(base + "/#demo/" + hash); };
  const source = async (id) => { await open("draft/" + id); await page.getByText("Задачи разбора", { exact: true }).waitFor(); };
  const confirm = async (count) => {
    const btn = page.getByRole("button", { name: "Подтвердить разбор", exact: true });
    await btn.waitFor();
    assert.equal(await btn.isEnabled(), true);
    const response = page.waitForResponse(r => r.url().endsWith("/drafts/prepared/confirm") && r.request().method() === "POST");
    await btn.click();
    const reply = await response;
    assert.equal(reply.status(), 200, await reply.text());
    const body = await reply.json();
    assert.equal(body.results.length, count);
    await page.waitForURL(/#demo\/drafts(\/chat\/|$)/);
    return body;
  };
  await open("drafts");
  await page.locator("tr.secband .shead").filter({ hasText: "Согласовать заведение" }).waitFor();
  await page.locator("tr.secband .shead").filter({ hasText: "Разбор и оформление" }).waitFor();
  const sectionRows = page.locator("tbody.tsec tr.dsrow");
  assert.equal(await sectionRows.count(), 4);
  assert.equal(await sectionRows.locator("button.dpick").count(), 0);
  for (const row of await sectionRows.all()) assert.equal(await row.locator("td").count(), 8);
  const p1row = sectionRows.filter({ has: page.locator("td.id", { hasText: "XR-005" }) });
  await p1row.locator("td.id").click();
  await page.waitForURL(/#demo\/draft\/XR-005(\/chat\/|$)/);
  await page.getByText("Задачи разбора", { exact: true }).waitFor();
  assert.equal(await page.locator("div.srow").count(), 2);
  assert.equal(await page.evaluate(() => {
    const comp=document.querySelector("#groups .comp"), body=document.querySelector("#groups .fbody");
    return Boolean(comp && body && comp.compareDocumentPosition(body) & Node.DOCUMENT_POSITION_FOLLOWING);
  }),true);
  await page.locator("div.srow").filter({ hasText: "первая карточка" }).click();
  await page.waitForURL(/#demo\/draft\/XR-005\/prepared\/p1/);
  await page.getByLabel("заголовок задачи p1").waitFor();
  assert.equal((await page.getByLabel("заголовок задачи p1").inputValue()).trim(), "первая карточка");
  assert.equal(await page.getByRole("button", { name: "Подтвердить", exact: true }).count(), 0);
  assert.equal(await page.getByRole("button", { name: "Отклонить", exact: true }).count(), 0);
  await page.getByText("из XR-005:", { exact: false }).first().click();
  await confirm(2);
  // Переход меняет URL раньше, чем refresh прочитает и отрисует список.
  console.log("rows immediately after navigation:", await page.locator("tbody.tsec tr.dsrow").count());
  await page.waitForFunction(() => document.querySelectorAll("tbody.tsec tr.dsrow").length === 3, null, { timeout: 10000 });
  assert.equal(await page.locator("tbody.tsec tr.dsrow").count(), 3);
  assert.equal(await page.locator("tbody.tsec tr.dsrow td.id").filter({ hasText: "XR-005" }).count(), 0);
  await source("XR-005");
  await page.getByText("История разбора", { exact: true }).waitFor();
  assert.equal(await page.getByRole("button", { name: "Подтвердить разбор", exact: true }).count(),0);
  assert.equal(await page.locator(".draft-idea").count(),0);
  await page.getByText("Ещё 2 решённые задачи", { exact: true }).click();
  assert.equal(await page.getByText("Подтверждено", { exact:true }).count(),2);
  for (const [id,count] of [["XR-006",2],["XR-007",1]]) { await source(id); await confirm(count); }
  await open("XR-001");
  await page.locator(".ffold .foldh").filter({ hasText: "Из черновика" }).click();
  await page.locator(".ffold").filter({ hasText: "третья карточка" }).first().waitFor();
  await page.getByRole("link", { name: "черновик XR-006", exact: true }).click();
  await page.waitForURL(/#demo\/draft\/XR-006/);
  await page.getByText("История разбора", { exact: true }).waitFor();
  await open("draft/XR-010/prepared/p5");
  await page.getByLabel("заголовок задачи p5").waitFor();
  const richChips = (await page.locator(".tchips .chip").allInnerTexts()).join(" | ");
  for (const part of ["На согласовании", "тип Баг", "ранг 42", "цена L", "Проверка с вашим участием"]) assert.ok(richChips.includes(part), richChips);
  await source("XR-010");
  const rich = await confirm(1);
  const ids = rich.results.flatMap(r=>r.ids || []);
  assert.ok(ids.length);
  await page.locator("#flashes").filter({ hasText:ids[0] }).waitFor();
  await source("XR-008");
  await page.getByText("Разбор ничего не подготовил. Можно подготовить задачу вручную.", { exact: true }).waitFor();
  await page.getByRole("button", { name: "Подготовить вручную", exact: true }).click();
  await page.waitForURL(/#demo\/draft\/XR-008\/prepared\/new/);
  await page.getByLabel("Исход").selectOption("drop");
  await page.getByLabel("текст файла задачи XR-008").fill("ручной исход");
  await page.locator("fieldset.dfield").filter({ hasText: "Причина" }).locator("textarea").fill("неактуально");
  const saved = page.waitForResponse(r=>r.url().endsWith("/XR-008/prepared") && r.request().method()==="PUT");
  await page.getByRole("button", { name: "Сохранить задачу", exact: true }).click();
  const savedResp = await saved;
  assert.equal(savedResp.status(), 200, await savedResp.text());
  const savedBody = await savedResp.json();
  const manualID = Object.values(savedBody.assigned || {})[0];
  assert.match(manualID || "", /^XR-[0-9]+$/);
  await page.waitForURL(new RegExp("#demo/draft/XR-008/prepared/" + manualID + "(/chat/)?$"));
  assert.equal(await page.getByRole("button", {name:"Подтвердить",exact:true}).count(),0);
  await source("XR-008"); await confirm(1);
  await source("XR-009");
  await page.getByText("Не удалось разобрать запись. Можно повторить разбор.", { exact: true }).waitFor();
  assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);
  await page.setViewportSize({width:1440,height:1000});
  await source("XR-006"); await page.getByText("История разбора",{exact:true}).waitFor();
  assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);
  const archived = await context.request.post(base + "/__archive");
  assert.equal(archived.status(),200,await archived.text());
  await open("XR-001");
  await page.locator(".ffold .foldh").filter({hasText:"Из черновика"}).click();
  await page.getByRole("link",{name:"черновик XR-006",exact:true}).click();
  await page.getByText("История разбора",{exact:true}).waitFor();
  console.log(JSON.stringify({sources:4,whole:true,history:true,attach:true,manual:true,widths:[390,1440]}));
} finally { await context.close(); await browser.close(); }
